      mandatory: { detention: ['+', 12], prisonocc: ['+', 20], prisoners: ['*', 1.25], courtwait: ['*', 1.2], trustcourt: ['+', -3], threats: ['*', 0.92], weapons: ['*', 0.92], govspend: ['+', 0.3] },
